window.piPull = async function () {
  var month = monthVal();
  msg('Pulling from portals (can take a few minutes)…', true);
  try {
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ month: month, channel: 'all' })
    });
    var r = await res.json();
    var errTxt = (r.errors || []).map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 3).join(' · ');
    if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    var n = (r.saved || []).length;
    if (n === 0) {
      msg('Portal pull saved 0 PDFs' + (errTxt ? (' — ' + errTxt) : '') +
        ' — use Upload and tag each Booking PDF to its apartment', false);
    } else {
      msg('Pulled ' + n + ' PDF(s)' + (errTxt ? (' · notes: ' + errTxt) : '') +
        '. Tag any Booking files to apartments below.', true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
};

