function piSessionHtml(st) {
  st = st || PI.status || {};
  var a = st.airbnbSession || {};
  var b = st.bookingSession || {};
  function chip(ok, label, when) {
    return '<span style="margin-right:10px">' +
      (ok ? '<span style="color:var(--tx-ok,#059669)">✓</span>' : '<span style="color:var(--tx-err,#b91c1c)">○</span>') +
      ' ' + label +
      (when ? (' <span style="color:var(--tx3);font-size:11px">(' + when + ')</span>') : '') +
      '</span>';
  }
  return '<div style="font-weight:600;margin-bottom:4px">Portal sessions</div>' +
    '<div>' + chip(!!a.connected, 'Airbnb', a.updatedAt ? String(a.updatedAt).slice(0, 16).replace('T', ' ') : '') +
    chip(!!b.connected, 'Booking.com', b.updatedAt ? String(b.updatedAt).slice(0, 16).replace('T', ' ') : '') + '</div>' +
    '<div style="margin-top:6px;color:var(--tx3);font-size:11.5px">Pull uses these sessions automatically and refreshes them after a successful login. One-time Connect only when captcha/OTP appears.</div>';
}
window.piRenderSessions = function () {
  var el = document.getElementById('pi-session-status');
  if (el) el.innerHTML = piSessionHtml(PI.status);
};
window.piConnectSession = async function (channel) {
  channel = String(channel || '').toLowerCase();
  var label = channel === 'booking' ? 'Booking.com' : 'Airbnb';
  var raw = prompt(
    'Paste ' + label + ' Playwright storageState JSON (from scripts/platform-invoice-save-session.js).\n' +
    'This is a one-time connect — not a PDF upload. After this, use Pull from portals.'
  );
  if (raw == null) return;
  raw = String(raw).trim();
  if (!raw) return;
  try {
    var state = null;
    if (raw.indexOf('{') === 0) state = JSON.parse(raw);
    else {
      try { state = JSON.parse(atob(raw.replace(/^.*?=/, ''))); }
      catch (e2) { state = JSON.parse(atob(raw)); }
    }
    var res = await fetch('/api/platform-invoices/sessions/' + encodeURIComponent(channel), {
      method: 'PUT', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ storageState: state })
    });
    var j = await res.json();
    if (!res.ok || !j.ok) throw new Error((j && j.error) || 'connect failed');
    msg(label + ' connected — running Pull…', true);
    await piReload();
    await piPull();
  } catch (e) { msg(e.message || String(e), false); }
};
window.piPull = async function () {
  var month = monthVal();
  var btn = document.getElementById('pi-pull-btn');
  if (btn) btn.disabled = true;
  msg('Pulling from portals (can take several minutes)…', true);
  try {
    var apts = ((PI.health && PI.health.bdcApts) || []).map(function (a) {
      return { aptId: a.aptId || '', aptName: a.aptName || '' };
    });
    if (!apts.length && typeof S !== 'undefined' && Array.isArray(S.apts)) {
      apts = S.apts.map(function (a) { return { aptId: a.id || a.aptId || '', aptName: a.name || a.aptName || '' }; });
    }
    var res = await fetch('/api/platform-invoices/pull', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ month: month, channel: 'all', apartments: apts })
    });
    var r = await res.json();
    var errTxt = (r.errors || []).map(function (e) {
      return (e.channel ? (e.channel + ': ') : '') + (e.property ? (e.property + ' — ') : '') + (e.error || e.hint || '');
    }).filter(Boolean).slice(0, 4).join(' · ');
    if (!res.ok) throw new Error((r.error || 'pull failed') + (r.hint ? (' — ' + r.hint) : '') + (errTxt ? (' · ' + errTxt) : ''));
    var n = (r.saved || []).length;
    if (n === 0) {
      msg('Automated pull saved 0 PDFs' + (errTxt ? (' — ' + errTxt) : '') +
        ' — Connect Airbnb/Booking session if login was blocked, then Pull again', false);
    } else {
      msg('Pulled ' + n + ' PDF(s) automatically' + (errTxt ? (' · notes: ' + errTxt) : ''), true);
    }
    await piHealth();
    await piReload();
  } catch (e) { msg(e.message || String(e), false); }
  finally { if (btn) btn.disabled = false; }
};

